; Trainer parties: see the party macros in macros/data.asm.
;	party FALKNER3, "Falkner"      ; the ID is checked against the party's place in its group
;	                               ; (optional third argument: DOUBLES, at least 2 Pokemon)
;	mon 8, SKARMORY                ; level offset (added to wBaseLevel), species
;		item LEFTOVERS             ; optional lines, in any order:
;		ability STURDY             ;   one of the species' abilities
;		moves DRILL_PECK, TOXIC    ;   1-4 moves, the other slots empty (none: level-up moves)
;		dvs PERFECT                ;   a DVS_* preset or dvs ATK, DEF, SPD, SPC
;		ev_spread HP_ATK           ;   an EVS_* preset
;		nickname "SKARM"
;		shiny
;	hard                           ; optional: the Hard mode team, same lines
;	mon 10, SKARMORY               ; (no hard line: Hard uses the team above)
;	end_party
; Random team: random_mons COUNT, LIST in place of the mon lines (either team;
; lists in data/trainers/random_parties.asm).

